INSERT INTO public.story_nodes VALUES (6, 1, 'CH1_DEVTOOLS_CUE', 'system', '{"scene": {"id": "CH1_DEVTOOLS_CUE", "bgm": "rain-and-little-storm-v1.mp3", "mode": "browser", "glitchLevel": 1}, "content": {"articleFooter": "[render warning] blocked resources detected / article body partially unavailable"}, "notifications": [{"body": "외부 리소스 응답 지연으로 본문 일부가 누락되었습니다.", "type": "system", "title": "페이지 렌더링 오류", "priority": "medium"}]}', 'inspect', '{"inspectTarget": "devtools_open", "allowedActions": ["inspect"]}', false, false, '2026-04-21 07:39:30.121237', '2026-04-23 05:39:32.095838');
