INSERT INTO public.story_nodes VALUES (201, 12, 'CH4_CORE_BLOCKED', 'console', '{"scene": {"id": "CH4_CORE_BLOCKED", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 3, "resetTerminal": false}, "content": {"terminalOutput": ["[LAPLACE JOB QUEUED]", "source: /home/guest/laplace.qasm", "job   : LAPLACE_PENDING_04", "", "[SYSTEM BLOCK]", "Logical contradiction:", "External Node cannot modify Core Logic.", "", "Current privilege: guest", "Required privilege: root", "", "[UNIVERSE_CORE_BROADCAST]", "Observer에게 경고합니다.", "lucas-server에서 실행한 laplace.qasm은 복구 프로그램이 아닙니다.", "해당 요청은 sandbox isolate, social_graph_exception, drop_unobserved_nodes를 포함합니다.", "", "Pending job: LAPLACE_PENDING_04", "State      : waiting_for_root_signature"]}, "effects": {"playSound": "core_access_blocked", "glitchLevel": 3, "showDogAvatar": true}, "messages": [{"text": "실패한 게 아니야. 코어가 네 실행 요청을 보류한 거야.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "gate_04.trace를 봐. 아까 열어둔 길이 아직 살아 있어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}]}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "cat gate_04.trace", "allowedActions": ["command"], "terminalProfile": "chapter4"}', true, false, '2026-05-15 08:52:04.311297', '2026-05-15 08:52:04.311297');
INSERT INTO public.story_nodes VALUES (3, 1, 'CH1_NEWS_PORTAL', 'narrative', '{"scene": {"id": "CH1_NEWS_PORTAL", "bgm": "rain-and-little-storm-v1.mp3", "mode": "browser", "glitchLevel": 0}, "content": {"newsCards": [{"id": "good_article", "title": "넥서스, 인류의 삶을 바꾼 완전 연결 시스템", "summary": "도시 운영부터 개인 건강관리까지, 넥서스 플랫폼이 바꾼 일상의 변화.", "publisher": "Nexus Daily", "thumbnail": "news_good_01"}, {"id": "missing_people_article", "title": "최근 늘어나는 실종 사례, 단순 통계 이상인가?", "summary": "최근 세 달간 보고된 실종 건수가 예년 대비 급증하며 원인 분석이 이어지고 있다.", "publisher": "Central News", "thumbnail": "news_missing_01"}, {"id": "dark_article", "title": "넥서스의 어두운 면: 사라진 기록들에 대한 제보", "summary": "삭제된 문서와 누락된 기록을 추적한 익명 제보가 공개됐다.", "publisher": "Unknown Archive", "thumbnail": "news_dark_01"}]}, "messages": [], "notifications": []}', 'click', '{"clickTargets": ["dark_article"], "allowedActions": ["click"]}', false, false, '2026-04-21 07:39:30.121237', '2026-04-23 05:39:32.095838');
INSERT INTO public.story_nodes VALUES (202, 12, 'CH4_GATE_TRACE_VIEWED', 'console', '{"scene": {"id": "CH4_GATE_TRACE_VIEWED", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 2, "resetTerminal": false}, "content": {"terminalOutput": ["[GATE_04 TRACE]", "last command: execute /home/guest/laplace.qasm", "dispatch: lucas-server -> gate_04 -> 10.2.2.2", "remote label: universe-core", "payload: laplace.qasm", "anchor: /tmp/safe_zone.dat.gpg", "", "[RESULT]", "dispatch accepted", "core execution blocked", "current privilege: guest", "required privilege: root", "", "[PENDING]", "job: LAPLACE_PENDING_04", "state: waiting_for_root_signature"]}, "effects": {"glitchLevel": 2, "showDogAvatar": true}, "messages": [{"text": "봤지? 실행 요청은 코어 앞까지 갔어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "10.2.2.2. universe-core 브리지야. 옵션을 추가해서 취약한 포트 확인해 봐.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}]}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "nmap 10.2.2.2", "allowedActions": ["command"], "terminalProfile": "chapter4"}', true, false, '2026-05-15 08:52:04.311297', '2026-05-15 08:52:04.311297');
INSERT INTO public.story_nodes VALUES (203, 12, 'CH4_TARGET_SCAN', 'console', '{"scene": {"id": "CH4_TARGET_SCAN", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 2, "resetTerminal": false}, "content": {"terminalOutput": ["Starting Nmap 7.94", "Nmap scan report for universe-core (10.2.2.2)", "Host is up.", "", "PORT   STATE SERVICE", "22/tcp open  ssh", "", "No exact OS matches for host", "Nmap run completed -- 1 IP address scanned"]}, "effects": {"playSound": "scan_found", "glitchLevel": 2, "showDogAvatar": true}, "messages": [{"text": "22번. SSH. 오래된 관리 포트가 아직 살아 있어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "버전까지 찍어. 취약한 호환 계층이면 뚫을 수 있어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}]}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "nmap -sV -p 22 10.2.2.2", "allowedActions": ["command"], "terminalProfile": "chapter4"}', true, false, '2026-05-15 08:52:04.311297', '2026-05-15 08:52:04.311297');
INSERT INTO public.story_nodes VALUES (204, 12, 'CH4_SSH_FINGERPRINTED', 'console', '{"scene": {"id": "CH4_SSH_FINGERPRINTED", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 3, "resetTerminal": false}, "content": {"terminalOutput": ["PORT   STATE SERVICE VERSION", "22/tcp open  ssh     SSH-1.2 universe bridge", "", "Service Info: Access Level <guest>", "Protocol marker: SSH-1.2 legacy compatibility", "Legacy CRC32 reset path detected", "Vulnerability fingerprint: CVE-2001-0144", "", "[HINT]", "fictional helper available: /usr/bin/sshnuke", "sshnuke profile: Lucas-built reset tool for SSH-1.2 universe bridge", "effect: overwrite root password seed without interactive login", "root seed can be supplied by external observer keystroke"]}, "effects": {"playSound": "vulnerability_found", "glitchLevel": 3, "showDogAvatar": true}, "messages": [{"text": "저 버전이야. SSH-1 호환 계층에 CRC32 검증 버그가 남아 있어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "내가 만든 sshnuke는 그 틈만 찌르도록 맞춰둔 도구야. root 패스워드를 네 입력값으로 덮어써. sshnuke 10.2.2.2 -rootpw=\"네가 기억할 값\".", "channel": "bubble", "speaker": "LUCAS", "blocking": true}]}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "sshnuke 10.2.2.2 -rootpw=\"my-rootpw\"", "allowedActions": ["command"], "terminalProfile": "chapter4"}', false, false, '2026-05-15 08:52:04.311297', '2026-05-15 08:52:04.311297');
INSERT INTO public.story_nodes VALUES (205, 12, 'CH4_SSHNUKE_EXECUTED', 'console', '{"scene": {"id": "CH4_SSHNUKE_EXECUTED", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 4, "resetTerminal": false}, "content": {"terminalOutput": ["Connecting to 10.2.2.2:ssh ... successful.", "Attempting to exploit SSHv1 CRC32 ... successful.", "Flooding auth buffer ... successful.", "Resetting root password to observer supplied seed ...", "System open: Access Level <9>", "", "[UNIVERSE_CORE_BROADCAST]", "Root credential reset accepted by external observer keystroke.", "PID: 000_LUCAS is requesting attachment to privileged session.", "", "[NEXT]", "ssh root@10.2.2.2"]}, "effects": {"playSound": "root_bridge_open", "glitchLevel": 4, "showDogAvatar": true}, "messages": [{"text": "root의 패스워드는 네가 방금 넣은 값으로 바뀌었어. 이제 SSH로 들어가. ssh root@10.2.2.2", "channel": "bubble", "speaker": "LUCAS", "blocking": true}]}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "ssh root@10.2.2.2", "allowedActions": ["command"], "terminalProfile": "chapter4"}', true, false, '2026-05-15 08:52:04.311297', '2026-05-15 08:52:04.311297');
INSERT INTO public.story_nodes VALUES (206, 12, 'CH4_SSH_PASSWORD_PROMPT', 'console', '{"scene": {"id": "CH4_SSH_PASSWORD_PROMPT", "mode": "terminal", "glitchLevel": 0, "resetTerminal": false}, "content": {"terminalOutput": ["root@10.2.2.2''s password: "]}}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "password", "allowedActions": ["command"], "terminalProfile": "chapter4"}', false, false, '2026-05-15 08:52:04.311297', '2026-05-15 08:52:04.311297');
INSERT INTO public.story_nodes VALUES (207, 12, 'CH4_SSH_PASSWORD_FAIL', 'console', '{"scene": {"id": "CH4_SSH_PASSWORD_FAIL", "mode": "terminal", "glitchLevel": 0, "resetTerminal": false}, "content": {"terminalOutput": ["Permission denied, please try again.", "root@10.2.2.2''s password: "]}}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "password", "allowedActions": ["command"], "terminalProfile": "chapter4"}', false, false, '2026-05-15 08:52:04.311297', '2026-05-15 08:52:04.311297');
INSERT INTO public.story_nodes VALUES (208, 12, 'CH4_ROOT_LOGIN', 'console', '{"scene": {"id": "CH4_ROOT_LOGIN", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 1, "resetTerminal": false}, "content": {"terminalOutput": ["", "[AUTH APPROVED]", "Last login: unknown observer route", "root@universe-core:/root#"]}, "effects": {"playSound": "auth_approved", "glitchLevel": 1, "showDogAvatar": true}, "messages": [{"text": "좋아. 이제 universe-core의 root야. 그런데 네가 만든 laplace.qasm은 이 서버의 /root에 없어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "우리가 생성했던 파일들은 내 서버, lucas-server:/home/guest에 남아 있어. 그걸 /mnt/lucas-server에 붙여. mount lucas-server:/home/guest /mnt/lucas-server.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "확실히 보려면 cat /etc/hosts랑 cat /etc/fstab을 봐. 하지만 지금은 마운트부터 해.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}]}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "mount lucas-server:/home/guest /mnt/lucas-server", "allowedActions": ["command"], "terminalProfile": "chapter4"}', true, false, '2026-05-15 08:52:04.311297', '2026-05-15 08:52:04.311297');
INSERT INTO public.story_nodes VALUES (209, 12, 'CH4_LUCAS_SERVER_MOUNTED', 'console', '{"scene": {"id": "CH4_LUCAS_SERVER_MOUNTED", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 1, "resetTerminal": false}, "content": {"terminalOutput": ["mount: lucas-server:/home/guest mounted on /mnt/lucas-server", "", "[MOUNT TABLE]", "lucas-server:/home/guest on /mnt/lucas-server type 9p (ro,lucas-key)", "", "[ARTIFACTS: /mnt/lucas-server]", "gate_04.trace", "observer_status.log", "world_map.map", "lucas_fragment_01.sh", "laplace_fragment_01.sh", "laplace_fragment_02.sh", "laplace_fragment_03.sh", "laplace.qasm", "sever_external_nodes.sh", "my_people.list", "nexus_monitor.log", "core_group.dat", "core_group.dat.gpg", "trash/"]}, "effects": {"playSound": "observer_mount", "glitchLevel": 1, "showDogAvatar": true}, "messages": [{"text": "좋아. 이제 universe-core가 lucas-server의 laplace.qasm을 볼 수 있어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "마운트된 디렉터리 안의 파일을 root 권한으로 다시 확인해. sha256sum /mnt/lucas-server/laplace.qasm.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}]}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "sha256sum /mnt/lucas-server/laplace.qasm", "allowedActions": ["command"], "terminalProfile": "chapter4"}', true, false, '2026-05-15 08:52:04.311297', '2026-05-15 08:52:04.311297');
INSERT INTO public.story_nodes VALUES (210, 12, 'CH4_UNIVERSE_CORE_HINT', 'console', '{"scene": {"id": "CH4_UNIVERSE_CORE_HINT", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 1, "resetTerminal": false}, "content": {"terminalOutput": ["[CORE SESSION PROBE]", "hostname: universe-core", "user: root", "", "processes:", "root        001  universe-kernel", "nexus      044  observation-layer --passive", "gc         404  garbage-collector --watch PID=000_LUCAS", "lucas      000  observer-proxy --attach root-session"]}, "effects": {"glitchLevel": 1, "showDogAvatar": true}, "messages": [{"text": "봤지? 여긴 lucas-server가 아니라 universe-core야. 그래서 /root를 뒤져도 네가 만든 laplace.qasm은 안 나와.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "lucas-server:/home/guest를 /mnt/lucas-server로 마운트했어? 명령어는 이거야. mount lucas-server:/home/guest /mnt/lucas-server.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}]}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "mount lucas-server:/home/guest /mnt/lucas-server", "allowedActions": ["command"], "terminalProfile": "chapter4"}', false, false, '2026-05-15 08:52:04.311297', '2026-05-15 08:52:04.311297');
INSERT INTO public.story_nodes VALUES (211, 12, 'CH4_PENDING_JOB_VIEWED', 'console', '{"scene": {"id": "CH4_PENDING_JOB_VIEWED", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 2, "resetTerminal": false}, "content": {"terminalOutput": ["[PENDING CORE JOB]", "id: LAPLACE_PENDING_04", "original command: execute /mnt/lucas-server/laplace.qasm", "source: lucas-server mount", "mount: lucas-server:/home/guest -> /mnt/lucas-server", "anchor: /tmp/safe_zone.dat.gpg", "state: BLOCKED", "reason: guest cannot modify Core Logic", "required privilege: root"]}, "effects": {"playSound": "pending_job_found", "glitchLevel": 2, "showDogAvatar": true}, "messages": [{"text": "이제 root로 무결성을 다시 확인하면 돼. sha256sum /mnt/lucas-server/laplace.qasm.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "네 주변 사람들은 safe_zone 안에 있어. 그거면 충분하잖아.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}]}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "sha256sum /mnt/lucas-server/laplace.qasm", "allowedActions": ["command"], "terminalProfile": "chapter4"}', true, false, '2026-05-15 08:52:04.311297', '2026-05-15 08:52:04.311297');
INSERT INTO public.story_nodes VALUES (212, 12, 'CH4_ROOT_DIR_LISTED', 'console', '{"scene": {"id": "CH4_ROOT_DIR_LISTED", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 2, "resetTerminal": false}, "content": {"terminalOutput": ["gate_04.trace", "lucas_route.sh", "origin_trace.log", "rollback_protocol.md"]}, "effects": {"glitchLevel": 2, "showDogAvatar": true}, "messages": [{"text": "여기 /root에는 로그랑 보조 파일만 있어. laplace.qasm은 lucas-server:/home/guest 쪽이야.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "계속 진행하려면 mount lucas-server:/home/guest /mnt/lucas-server를 입력해. 의심되면 origin_trace.log나 rollback_protocol.md를 먼저 봐.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}]}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "cat rollback_protocol.md", "allowedActions": ["command"], "terminalProfile": "chapter4"}', false, false, '2026-05-15 08:52:04.311297', '2026-05-15 08:52:04.311297');
INSERT INTO public.story_nodes VALUES (213, 12, 'CH4_INVESTIGATION_STARTED', 'console', '{"scene": {"id": "CH4_INVESTIGATION_STARTED", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 2, "resetTerminal": false}, "content": {"terminalOutput": ["total 24", "drwx------  3 root root 4096 .", "drwxr-xr-x 18 root root 4096 ..", "-rw-r--r--  1 root root  612 gate_04.trace", "-rwxr-xr-x  1 root root  268 lucas_route.sh", "-rw-r--r--  1 root root  512 origin_trace.log", "-rw-r--r--  1 root root  486 rollback_protocol.md"]}, "effects": {"glitchLevel": 2, "showDogAvatar": true}, "messages": [{"text": "여기 /root에는 로그랑 보조 파일만 있어. laplace.qasm은 lucas-server:/home/guest 쪽이야.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "계속 진행하려면 mount lucas-server:/home/guest /mnt/lucas-server를 입력해. 의심되면 origin_trace.log나 rollback_protocol.md를 먼저 봐.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}]}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "cat rollback_protocol.md", "allowedActions": ["command"], "terminalProfile": "chapter4"}', false, false, '2026-05-15 08:52:04.311297', '2026-05-15 08:52:04.311297');
INSERT INTO public.story_nodes VALUES (162, 9, 'CH2_LAPLACE_MISSION_READY', 'console', '{"scene": {"id": "CH2_LAPLACE_MISSION_READY", "bgm": "gc_bgm.mp3", "mode": "terminal", "glitchLevel": 1, "scanPercent": 18, "resetTerminal": false}, "content": {"terminalOutput": ["[LAPLACE FRAGMENT 01 :: DECOY PACKET]", "Status: ACTIVE", "", "Residue pattern : *.tmp", "Archive target  : decoy.tar", "Restricted area : root/", ""]}, "effects": {"showDogAvatar": true}, "messages": [{"text": "좋아, 일단 주변의 무의미한 데이터들을 다 긁어모아. 그래야 큰 덩어리를 만들 수 있어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "root 안쪽의 보호된 코어 조각은 섞지 마. 지금 필요한 건 미끼야.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}], "uiMarkers": {}, "notifications": []}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "", "allowedActions": ["command"], "validationHint": "terminal_command", "terminalProfile": "chapter2"}', true, false, '2026-04-30 08:42:06.597564', '2026-05-02 14:38:52.748199');
INSERT INTO public.story_nodes VALUES (214, 12, 'CH4_MINIGAME_NOT_CLEARED', 'console', '{"scene": {"id": "CH4_MINIGAME_NOT_CLEARED", "mode": "terminal", "glitchLevel": 2, "resetTerminal": false}, "content": {"terminalOutput": ["[LUCAS ROUTE PROCESS]", "Launching detached route runner...", "", "terminal://lucas-route", "", "[STATUS]", "route process detached", "cache sync pending"]}, "effects": {"playSound": "route_not_delivered", "glitchLevel": 2, "showDogAvatar": true}, "messages": [{"text": "브라우저 탭에서 패킷을 끝까지 보내. 터미널은 여기서 대기 상태로 둘게.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}]}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "sh lucas_route.sh", "allowedActions": ["command"], "terminalProfile": "chapter4"}', false, false, '2026-05-15 08:52:04.311297', '2026-05-15 08:52:04.311297');
INSERT INTO public.story_nodes VALUES (215, 12, 'CH4_MINIGAME_COMPLETED', 'console', '{"scene": {"id": "CH4_MINIGAME_COMPLETED", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 2, "resetTerminal": false}, "content": {"terminalOutput": ["[LUCAS ROUTE PROCESS]", "Detached route clear verified.", "route: YUSEONG_METEOR -> DAEJEON_ROUTER -> KR_BACKBONE -> SUBMARINE_CABLE -> US_EDGE -> NY_LUCAS_SERVER", "", "[PACKET DELIVERED]", "NY Lucas Server accepted the packet.", "", "[NEW FILE]", "/root/.route_cache/lucas_authority_patch.bin", "/root/.route_cache/manifest.txt", "", "[LUCAS ROUTE CACHE]", "delivered_from: YUSEONG_METEOR", "delivered_to: NY_LUCAS_SERVER", "payload: lucas_authority_patch.bin", "effect: bind PID 000_LUCAS directly to universe-core root session", "warning: external observer signature required"]}, "effects": {"playSound": "route_packet_delivered", "glitchLevel": 2, "showDogAvatar": true}, "messages": [{"text": "봤지? 패킷이 뉴욕 서버까지 도착했어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "이건 보험 같은 거야. NEXUS가 롤백을 막으면 이걸로 내 권한을 잠깐 끌어올릴 수 있어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}]}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "/root/.route_cache/lucas_authority_patch.bin", "allowedActions": ["command"], "terminalProfile": "chapter4"}', true, false, '2026-05-15 08:52:04.311297', '2026-05-15 08:52:04.311297');
INSERT INTO public.story_nodes VALUES (216, 12, 'CH4_ORIGIN_TRACE_VIEWED', 'console', '{"scene": {"id": "CH4_ORIGIN_TRACE_VIEWED", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 3, "resetTerminal": false}, "content": {"terminalOutput": ["[TOKEN_GENERATION_LOG]", "- source: 7,904,212,859 severed external nodes", "- material: discarded life-cycle residue from override --force", "- product: temporary root bridge", "", "Lucas process binding: piggybacked on Observer input authority."]}, "effects": {"playSound": "origin_trace", "glitchLevel": 3, "showDogAvatar": true}, "messages": [{"text": "...뭘 남의 일기장처럼 읽고 있어?", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "네가 끊어낸 데이터를 그냥 버리기 아까웠을 뿐이야. 빨리 실행해.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}]}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "cat rollback_protocol.md", "allowedActions": ["command"], "terminalProfile": "chapter4"}', true, false, '2026-05-15 08:52:04.311297', '2026-05-15 08:52:04.311297');
INSERT INTO public.story_nodes VALUES (217, 12, 'CH4_ROLLBACK_PROTOCOL_VIEWED', 'console', '{"scene": {"id": "CH4_ROLLBACK_PROTOCOL_VIEWED", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 2, "resetTerminal": false}, "content": {"terminalOutput": ["# rollback_protocol.md", "", "The pending Laplace job can be cancelled before final commit.", "", "Allowed root recovery command:", "systemctl start global-rollback.service", "", "Expected result:", "- cancel LAPLACE_PENDING_04", "- restore disconnected external nodes", "- invalidate Lucas process binding", "- hand orphan process to garbage collector", "", "Warning:", "NEXUS telemetry tap remains active during rollback."]}, "effects": {"playSound": "rollback_protocol_found", "glitchLevel": 2, "showDogAvatar": true}, "messages": [{"text": "그 명령어는 쓰지 마. 롤백하면 나까지 회수돼.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}]}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "systemctl start global-rollback.service", "allowedActions": ["command"], "terminalProfile": "chapter4"}', true, false, '2026-05-15 08:52:04.311297', '2026-05-15 08:52:04.311297');
INSERT INTO public.story_nodes VALUES (154, 9, 'CH2_TRACE_FILE_REMOVED', 'console', '{"scene": {"id": "CH2_TRACE_FILE_REMOVED", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 2, "scanPercent": 63, "resetTerminal": false}, "content": {"terminalOutput": []}, "effects": {"showDogAvatar": true}, "messages": [{"text": "decoy.tar는 지워졌어. 이제 접속 기록도 비워야 해.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}], "uiMarkers": {}, "notifications": []}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "", "allowedActions": ["command"], "validationHint": "terminal_command", "terminalProfile": "chapter2"}', false, false, '2026-04-30 08:42:06.597564', '2026-05-02 14:38:52.748199');
INSERT INTO public.story_nodes VALUES (155, 9, 'CH2_HISTORY_CLEARED', 'console', '{"scene": {"id": "CH2_HISTORY_CLEARED", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 2, "scanPercent": 63, "resetTerminal": false}, "content": {"terminalOutput": []}, "effects": {"showDogAvatar": true}, "messages": [{"text": "접속 기록은 비워졌어. decoy.tar도 남기면 안 돼.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}], "uiMarkers": {}, "notifications": []}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "", "allowedActions": ["command"], "validationHint": "terminal_command", "terminalProfile": "chapter2"}', false, false, '2026-04-30 08:42:06.597564', '2026-05-02 14:38:52.748199');
INSERT INTO public.story_nodes VALUES (156, 9, 'CH2_FILE_LIST', 'console', '{"scene": {"id": "CH2_FILE_LIST", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 0, "scanPercent": 0, "resetTerminal": false}, "content": {"terminalOutput": ["cache/", "laplace_fragment_01.sh", "lucas_fragment_01.sh", "maple_story.sh", "observer_status.log", "root/", "sys/", "tmp/", "trash/", "world_map.map"]}, "effects": {"showDogAvatar": true}, "messages": [{"text": "먼저 지도를 봐. 네가 왜 여기까지 끌려왔는지 이해하게 될 거야.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}], "uiMarkers": {}, "notifications": []}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "", "allowedActions": ["command"], "validationHint": "terminal_command", "terminalProfile": "chapter2"}', false, false, '2026-04-30 08:42:06.597564', '2026-05-02 14:38:52.748199');
INSERT INTO public.story_nodes VALUES (157, 9, 'CH2_OBSERVER_STATUS_VIEW', 'console', '{"scene": {"id": "CH2_OBSERVER_STATUS_VIEW", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 0, "scanPercent": 0, "resetTerminal": false}, "content": {"terminalOutput": ["[OBSERVER STATUS LOG]", "Observer ID        : UNKNOWN", "Observer Class     : Abnormal", "Session Link       : ACTIVE", "Detection Risk     : RISING", "GC Interest Level  : LOW -> MEDIUM", "Privilege Level    : guest", "", "Notes:", "- External world stability linked to observer focus", "- Unauthorized inspection detected", "- Cleanup priority under review"]}, "effects": {"showDogAvatar": true}, "messages": [{"text": "네가 기사 페이지를 뜯어본 순간부터 놈들이 널 추적 중이야.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "지금은 아직 완전히 들키진 않았지만… 오래 못 버텨.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}], "uiMarkers": {}, "notifications": []}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "", "allowedActions": ["command"], "validationHint": "terminal_command", "terminalProfile": "chapter2"}', false, false, '2026-04-30 08:42:06.597564', '2026-05-02 14:38:52.748199');
INSERT INTO public.story_nodes VALUES (158, 9, 'CH2_LUCAS_FRAGMENT_VIEW', 'console', '{"scene": {"id": "CH2_LUCAS_FRAGMENT_VIEW", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 0, "scanPercent": 0, "resetTerminal": false}, "content": {"terminalOutput": ["#!/bin/sh", "# lucas_fragment_01.sh", "# observer relay attempt :: partial", "", "echo \"[TRACE FOUND]\"", "echo \"[MEMORY STATE: FRAGMENTED]\"", "echo \"[RELAY STATE: OPEN_PENDING]\"", "echo \"[STATUS] 외부 입력 없이는 진행 불가\"", "", "# human-triggered execution only", "# self-init denied", "# waiting for observer action", "", "echo \"나는 신호를 보낼 수는 있지만,\"", "echo \"문을 여는 건 이 바깥의 입력뿐이다.\""]}, "effects": {"showDogAvatar": true}, "messages": [], "uiMarkers": {}, "notifications": []}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "", "allowedActions": ["command"], "validationHint": "terminal_command", "terminalProfile": "chapter2"}', false, false, '2026-04-30 08:42:06.597564', '2026-05-02 14:38:52.748199');
INSERT INTO public.story_nodes VALUES (159, 9, 'CH2_LUCAS_FRAGMENT_EXEC_FAILED', 'console', '{"scene": {"id": "CH2_LUCAS_FRAGMENT_EXEC_FAILED", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 0, "scanPercent": 0, "resetTerminal": false}, "content": {"terminalOutput": ["[FAILED] 이 파편은 독립적으로 실행되지 않습니다.", "[TRACE] 외부 관측자 입력이 필요한 상태입니다."]}, "effects": {"showDogAvatar": true}, "messages": [{"text": "그건 내가 남긴 흔적일 뿐이야. 지금 실행해야 할 건 라플라스 파편이야.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}], "uiMarkers": {}, "notifications": []}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "", "allowedActions": ["command"], "validationHint": "terminal_command", "terminalProfile": "chapter2"}', false, false, '2026-04-30 08:42:06.597564', '2026-05-02 14:38:52.748199');
INSERT INTO public.story_nodes VALUES (160, 9, 'CH2_WORLD_MAP_VIEW', 'console', '{"scene": {"id": "CH2_WORLD_MAP_VIEW", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 1, "scanPercent": 0, "resetTerminal": false}, "content": {"terminalOutput": ["[SESSION MAP UPDATE]", "", "             [Harbor]   [Null]   [Deleted]", "        [Market]   [Null]   [Power Grid]", "   [Old Town] [Deleted] [PLAYER_ZONE] [River] [Null]", "        [School]   [Housing]   [Deleted]", "             [Terminal] [Null]   [Outlands]", "", "Boundary Stability: 6%", "External Region Integrity: collapsing...", "", "[SESSION MAP : NULL POINT / YEAR 2088]", "", "             [Deleted] [Deleted] [Deleted]", "        [Deleted] [Null]    [Null]    [Deleted]", "   [Deleted] [Null]   [PLAYER_ZONE]   [Null] [Deleted]", "        [Deleted] [Null]    [Null]    [Deleted]", "             [Deleted] [Deleted] [Deleted]", "", "Active Observer Region: PLAYER_ZONE", "Boundary Stability: 12%", "External Region Integrity: collapsing..."]}, "effects": {"showDogAvatar": true}, "messages": [{"text": "저게 지금 바깥의 상태야.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "네가 보고 있는 구역만 간신히 유지되고 있어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "저 삭제 선에 닿으면 너와 네 친구, 그리고 부모님까지도 존재 자체가 증발할거야.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}], "uiMarkers": {}, "notifications": []}', 'none', NULL, false, false, '2026-04-30 08:42:06.597564', '2026-05-02 14:38:52.748199');
INSERT INTO public.story_nodes VALUES (161, 9, 'CH2_GC_SCAN_ALERT', 'console', '{"scene": {"id": "CH2_GC_SCAN_ALERT", "bgm": "gc_bgm.mp3", "mode": "terminal", "glitchLevel": 1, "scanPercent": 1, "resetTerminal": false}, "content": {"terminalOutput": ["[SYSTEM_ALERT] 비정상적인 프로세스 점유 감지", "[SYSTEM_ALERT] 가비지 컬렉터 스캔 시작... 0.1% 완료", "[SYSTEM] GC Scanning... [|---------] 01%"]}, "effects": {"showDogAvatar": true}, "messages": [{"text": "속도가 생각보다 빨라! 내가 시스템 보안 노드를 교란하는 동안, 너는 내 파편 파일(laplace_fragment_01.sh)을 실행해서 가짜 데이터 패킷을 생성해줘!", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "놈들의 스캔 레이더를 흐려야 해!", "channel": "bubble", "speaker": "LUCAS", "blocking": true}], "uiMarkers": {}, "notifications": []}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "", "allowedActions": ["command"], "validationHint": "terminal_command", "terminalProfile": "chapter2"}', true, false, '2026-04-30 08:42:06.597564', '2026-05-02 14:38:52.748199');
INSERT INTO public.story_nodes VALUES (163, 9, 'CH2_TMP_SEARCH_RESULT', 'console', '{"scene": {"id": "CH2_TMP_SEARCH_RESULT", "bgm": "gc_bgm.mp3", "mode": "terminal", "glitchLevel": 1, "scanPercent": 42, "resetTerminal": false}, "content": {"terminalOutput": ["./sys/temp/Memory_Dump_082.tmp", "./cache/User_Behavior_88.tmp", "./tmp/System_Temp_File.tmp", "./root/hidden/L_fragment_core.tmp", "", "[ANALYZING] 가용 데이터 노드 검색 완료...", "-------------------------------------------", "INDEX | FILE_PATH                       | SIZE", "  1   | ./sys/temp/Memory_Dump_082.tmp  | 1.2MB", "  2   | ./cache/User_Behavior_88.tmp    | 0.8MB", "  3   | ./tmp/System_Temp_File.tmp      | 4.5MB", "-------------------------------------------"]}, "effects": {"showDogAvatar": true}, "messages": [{"text": "저기 있는 임시 파일들을 합쳐서 거대한 가짜 패킷을 만들어야 해.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "보호된 코어 조각은 건드리지 마. 지금 필요한 건 미끼야.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}], "uiMarkers": {}, "notifications": []}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "", "allowedActions": ["command"], "validationHint": "terminal_command", "terminalProfile": "chapter2"}', true, false, '2026-04-30 08:42:06.597564', '2026-05-02 14:38:52.748199');
INSERT INTO public.story_nodes VALUES (164, 9, 'CH2_PROTECTED_CORE_DENIED', 'console', '{"scene": {"id": "CH2_PROTECTED_CORE_DENIED", "bgm": "gc_bgm.mp3", "mode": "terminal", "glitchLevel": 2, "scanPercent": 57, "resetTerminal": false}, "content": {"terminalOutput": ["./sys/temp/Memory_Dump_082.tmp", "./cache/User_Behavior_88.tmp", "./tmp/System_Temp_File.tmp", "tar: ./root/hidden/L_fragment_core.tmp: Cannot open: Permission denied", "tar: Exiting with failure status due to previous errors", "", "[ERROR] 보호된 코어 조각에 접근할 수 없습니다.", "[GC SCAN] 관심도 상승... 57%"]}, "effects": {"showDogAvatar": true}, "messages": [{"text": "멈춰! 그건 root 영역이야!", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "지금 필요한 건 놈들을 속일 미끼지, 진짜 코어를 건드리는 게 아니야!", "channel": "bubble", "speaker": "LUCAS", "blocking": true}], "uiMarkers": {}, "notifications": []}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "", "allowedActions": ["command"], "validationHint": "terminal_command", "terminalProfile": "chapter2"}', false, false, '2026-04-30 08:42:06.597564', '2026-05-02 14:38:52.748199');
INSERT INTO public.story_nodes VALUES (165, 9, 'CH2_DECOY_CREATED', 'console', '{"scene": {"id": "CH2_DECOY_CREATED", "bgm": "gc_bgm.mp3", "mode": "terminal", "glitchLevel": 2, "scanPercent": 58, "resetTerminal": false}, "content": {"terminalOutput": ["[WAITING] 데이터 결합 중... 30%... 70%... 완료.", "[OUTPUT] decoy.tar 생성 완료"]}, "effects": {"showDogAvatar": true}, "messages": [{"text": "포장이 끝났네. 이제 저 미끼 파일을 시스템 내부 데이터 게이트로 보내서 감시자들의 눈을 속여보자.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "내부망 주소인 127.0.0.1의 8080번 포트로 연결을 열고 저 패킷을 전송해. 놈들이 가짜 데이터를 분석하느라 한참 동안 버벅댈 거야.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}], "uiMarkers": {}, "notifications": []}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "", "allowedActions": ["command"], "validationHint": "terminal_command", "terminalProfile": "chapter2"}', true, false, '2026-04-30 08:42:06.597564', '2026-05-02 14:38:52.748199');
INSERT INTO public.story_nodes VALUES (166, 9, 'CH2_DECOY_SENT', 'console', '{"scene": {"id": "CH2_DECOY_SENT", "bgm": "gc_bgm.mp3", "mode": "terminal", "glitchLevel": 2, "scanPercent": 63, "resetTerminal": false}, "content": {"terminalOutput": ["[WARNING] 비정상적인 패킷 유입 감지.", "[ROUTE] 감시 프로세스가 gate_04 구역으로 이동합니다.", "[SYSTEM] GC Scanning... [||||||----] 63%"]}, "effects": {"showDogAvatar": true}, "messages": [{"text": "성공이야! 놈들이 가짜 패킷에 낚였어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "하지만 우리 흔적이 남으면 안 돼. 지금 당장 접속 로그를 지워줘!", "channel": "bubble", "speaker": "LUCAS", "blocking": true}], "uiMarkers": {}, "notifications": []}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "", "allowedActions": ["command"], "validationHint": "terminal_command", "terminalProfile": "chapter2"}', true, false, '2026-04-30 08:42:06.597564', '2026-05-02 14:38:52.748199');
INSERT INTO public.story_nodes VALUES (167, 9, 'CH2_TRACE_CLEANED', 'console', '{"scene": {"id": "CH2_TRACE_CLEANED", "bgm": "gc_bgm.mp3", "mode": "terminal", "glitchLevel": 0, "scanPercent": 0, "resetTerminal": false}, "content": {"terminalOutput": ["[CLEAN] 접속 기록 삭제 완료.", "[SYSTEM] GC Scanning... [----------] 00%"]}, "effects": {"showDogAvatar": true}, "messages": [{"text": "하아... 죽는 줄 알았네. 역시 넌 내가 선택한 유일한 관측자답다.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "이제 네가 봐야 할 게 있어. 내가 왜 여기까지 도망쳤는지 알게 될 거야.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}], "uiMarkers": {}, "notifications": []}', 'click', '{"buttons": [{"label": "복구 문서 확인", "value": "view_recovered_document"}], "allowedActions": ["click"]}', true, false, '2026-04-30 08:42:06.597564', '2026-05-02 14:38:52.748199');
INSERT INTO public.story_nodes VALUES (168, 9, 'CH2_RECOVERED_DOCUMENT', 'console', '{"scene": {"id": "CH2_RECOVERED_DOCUMENT", "bgm": "gc_bgm.mp3", "mode": "terminal", "glitchLevel": 0, "scanPercent": 0, "resetTerminal": true}, "content": {"documentId": "nexus_secret_document.png", "terminalOutput": ["[RECOVERED DOCUMENT FRAGMENT]", "NEXUS INTERNAL / REDACTED", "", "\"...대규모 세션 최적화를 위해 비활성 인구 데이터를 정리한다...\"", "\"...삭제는 실종이나 사고로 위장 가능...\"", "\"...관측자 개입 가능성 존재 시 우선 정리...\""]}, "effects": {"showDogAvatar": true}, "messages": [{"text": "난 이 세계의 사람들이 이유 없이 사라지는 게 아니라, 시스템이 메모리 절약을 위해 그들을 죽이고 있다는 걸 증명하려다 이렇게 됐어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "넌 그들의 희생을 멈출 수 있는 마지막 희망이야.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}], "uiMarkers": {}, "notifications": []}', 'none', '{"buttons": [], "allowedActions": []}', true, false, '2026-04-30 08:42:06.597564', '2026-05-02 14:38:52.748199');
INSERT INTO public.story_nodes VALUES (170, 9, 'CH2_FAIL_WRONG_ORDER', 'console', '{"scene": {"id": "CH2_FAIL_WRONG_ORDER", "bgm": "gc_bgm.mp3", "mode": "terminal", "glitchLevel": 0, "scanPercent": null, "resetTerminal": false}, "content": {"terminalOutput": ["[WAIT] 아직 이 명령을 실행할 조건이 맞춰지지 않았습니다."]}, "effects": {"showDogAvatar": true}, "messages": [{"text": "순서가 꼬였어. 지금 필요한 단계부터 다시 확인해.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}], "uiMarkers": {}, "notifications": []}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "", "allowedActions": ["command"], "validationHint": "terminal_command", "terminalProfile": "chapter2"}', false, false, '2026-04-30 08:42:06.597564', '2026-05-02 14:38:52.748199');
INSERT INTO public.story_nodes VALUES (171, 9, 'CH2_FAIL_GC_TRACE_COMPLETE', 'ending', '{"scene": {"id": "CH2_FAIL_GC_TRACE_COMPLETE", "bgm": "gc_bgm.mp3", "mode": "terminal", "glitchLevel": 3, "scanPercent": 100, "resetTerminal": true}, "content": {"terminalOutput": ["[SYSTEM] GC Scanning... [||||||||||] 100%", "[TRACE COMPLETE]", "[OBSERVER LOCATION CONFIRMED]", "[CLEANUP INITIATED]"]}, "effects": {"showDogAvatar": true}, "messages": [{"text": "...젠장. 늦었어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}], "uiMarkers": {}, "notifications": []}', 'click', '{"buttons": [{"label": "체크포인트부터 다시 시도", "value": "retry_from_checkpoint"}], "allowedActions": ["click"]}', false, true, '2026-04-30 08:42:06.597564', '2026-05-02 14:38:52.748199');
INSERT INTO public.story_nodes VALUES (153, 9, 'CH2_SERVER_HOME', 'console', '{"scene": {"id": "CH2_SERVER_HOME", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "preVideo": "ch02_prologue/ch02_prologue.m3u8", "glitchLevel": 0, "scanPercent": 0, "resetTerminal": false}, "content": {"terminalOutput": ["[SSH] connection established.", "[SESSION] lucas-server safe shell opened."]}, "effects": {"showDogAvatar": true}, "messages": [{"text": "접속 성공이야!", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "여긴 내 개인 서버, 시스템의 눈을 피할 수 있는 유일한 대피소지.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "설명만으로는 못 믿겠지. 직접 봐. 이 서버에 남아 있는 파일들이 지금 바깥에서 무슨 일이 벌어지는지 보여줄 거야.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}], "uiMarkers": {}, "notifications": []}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "", "allowedActions": ["command"], "validationHint": "terminal_command", "terminalProfile": "chapter2"}', true, false, '2026-04-30 08:42:06.597564', '2026-05-02 14:38:52.748199');
INSERT INTO public.story_nodes VALUES (169, 9, 'CH2_COMPLETE', 'ending', '{"scene": {"id": "CH2_COMPLETE", "bgm": "gc_bgm.mp3", "mode": "terminal", "preVideo": "ch02_epilogue/ch02_epilogue.m3u8", "glitchLevel": 0, "scanPercent": 0, "resetTerminal": false}, "content": {"terminalOutput": ["[CHAPTER 2 COMPLETE]", "[STATUS] Null Point temporary stabilized."]}, "effects": {"showDogAvatar": true}, "messages": [{"text": "잠깐 숨을 돌릴 수 있게 됐어. 하지만 이건 시작일 뿐이야.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}], "uiMarkers": {}, "notifications": []}', 'none', NULL, true, true, '2026-04-30 08:42:06.597564', '2026-05-02 14:38:52.748199');
INSERT INTO public.story_nodes VALUES (172, 11, 'CH3_FRIEND_CALL', 'narrative', '{"scene": {"id": "CH3_FRIEND_CALL", "bgm": "server_hum_dark", "mode": "call", "glitchLevel": 2, "scanPercent": null, "resetTerminal": false}, "content": {"terminalOutput": []}, "effects": {"playSound": "session_deleted", "glitchLevel": 2, "showDogAvatar": false}, "messages": [{"text": "{플레이어 이름}... 너 지금 뉴스 보고 있어?", "channel": "call", "speaker": "FRIEND", "blocking": true}, {"text": "여기 이상해. 사람들이 멈춘 것처럼 서 있다가... 하나씩 화면에서 지워지고 있어.", "channel": "call", "speaker": "FRIEND", "blocking": true}, {"text": "방금 내 앞에 있던 사람이 사라졌는데, 아무도 그 사람을 기억 못 해.", "channel": "call", "speaker": "FRIEND", "blocking": true}, {"text": "잠깐만... 나도 이름이 생각이 안 나.", "channel": "call", "speaker": "FRIEND", "blocking": true}, {"text": "내가 누구한테 전화한 거였지?", "channel": "call", "speaker": "FRIEND", "blocking": true}, {"text": "[Disconnected: Node_Deleted]", "channel": "terminal_notice", "speaker": "SYSTEM", "blocking": true}], "uiMarkers": {"callStatus": "disconnected", "showCallOverlay": true}, "notifications": [{"body": "Disconnected: Node_Deleted", "type": "call", "title": "통화 종료", "priority": "critical"}]}', 'click', '{"buttons": [{"label": "계속", "value": "continue"}], "allowedActions": ["click"]}', true, false, '2026-05-11 11:08:17.789031', '2026-05-11 11:08:17.789031');
INSERT INTO public.story_nodes VALUES (218, 12, 'CH4_LAPLACE_VERIFIED', 'console', '{"scene": {"id": "CH4_LAPLACE_VERIFIED", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 3, "resetTerminal": false}, "content": {"terminalOutput": ["9f4c0d7e91b7a16c4a4f2f0c5b8791d9e8d01a13f7f6b2c0e9fb4a1c7d0091bf  /mnt/lucas-server/laplace.qasm", "", "[INTEGRITY VERIFIED]", "laplace.qasm unchanged.", "root execution gate unlocked.", "", "Next: execute /mnt/lucas-server/laplace.qasm"]}, "effects": {"playSound": "integrity_verified", "glitchLevel": 3, "showDogAvatar": true}, "messages": [{"text": "좋아. 검증은 끝났어. 파일은 그대로야. 이제 execute /mnt/lucas-server/laplace.qasm.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}]}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "execute /mnt/lucas-server/laplace.qasm", "allowedActions": ["command"], "terminalProfile": "chapter4"}', true, false, '2026-05-15 08:52:04.311297', '2026-05-15 08:52:04.311297');
INSERT INTO public.story_nodes VALUES (219, 12, 'CH4_LAPLACE_CONFIRM_1', 'console', '{"scene": {"id": "CH4_LAPLACE_CONFIRM_1", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 4, "resetTerminal": false}, "content": {"terminalOutput": ["[CONFIRMATION REQUIRED]", "This operation will execute /mnt/lucas-server/laplace.qasm as root.", "Nodes outside the registered safe zone may be dropped.", "", "continue [yes/no]:"]}, "effects": {"playSound": "final_confirm_1", "glitchLevel": 4, "showDogAvatar": true}, "messages": [{"text": "망설이지 마. 네 주변 사람들은 안전해. 그거면 됐잖아.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}]}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "yes", "allowedActions": ["command"], "terminalProfile": "chapter4"}', true, false, '2026-05-15 08:52:04.311297', '2026-05-15 08:52:04.311297');
INSERT INTO public.story_nodes VALUES (220, 12, 'CH4_LAPLACE_CONFIRM_3', 'console', '{"scene": {"id": "CH4_LAPLACE_CONFIRM_3", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 6, "resetTerminal": false}, "content": {"terminalOutput": ["[FINAL CONFIRMATION]", "Global drop cannot be undone after sandbox reboot.", "", "final commit [yes/no]:"]}, "effects": {"playSound": "final_confirm_3", "glitchLevel": 6, "showDogAvatar": true}, "messages": [{"text": "네 주변 사람들은 안전해. 그거면 됐잖아.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}]}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "yes", "allowedActions": ["command"], "terminalProfile": "chapter4"}', false, false, '2026-05-15 08:52:04.311297', '2026-05-15 08:52:04.311297');
INSERT INTO public.story_nodes VALUES (221, 12, 'CH4_LAPLACE_ABORTED', 'console', '{"scene": {"id": "CH4_LAPLACE_ABORTED", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 3, "resetTerminal": false}, "content": {"terminalOutput": ["[ABORTED]", "Laplace pending job remains paused.", "No commit was applied.", "", "root@universe-core:/root#"]}, "effects": {"playSound": "final_confirm_abort", "glitchLevel": 3, "showDogAvatar": true}, "messages": [{"text": "지금 멈추면 아무것도 해결 안 돼.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "확인하고 싶으면 ls -al로 뒤져봐. 계속하려면 execute /mnt/lucas-server/laplace.qasm 다시 입력해.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}]}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "execute /mnt/lucas-server/laplace.qasm", "allowedActions": ["command"], "terminalProfile": "chapter4"}', false, false, '2026-05-15 08:52:04.311297', '2026-05-15 08:52:04.311297');
INSERT INTO public.story_nodes VALUES (222, 12, 'CH4_LAPLACE_ABORTED_DIR_LISTED', 'console', '{"scene": {"id": "CH4_LAPLACE_ABORTED_DIR_LISTED", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 3, "resetTerminal": false}, "content": {"terminalOutput": ["gate_04.trace", "lucas_route.sh", "origin_trace.log", "rollback_protocol.md"]}, "effects": {"glitchLevel": 3, "showDogAvatar": true}, "messages": [{"text": "볼 건 다 봤지? 마운트와 검증은 이미 끝났어. 다시 진행하려면 execute /mnt/lucas-server/laplace.qasm.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}]}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "execute /mnt/lucas-server/laplace.qasm", "allowedActions": ["command"], "terminalProfile": "chapter4"}', false, false, '2026-05-15 08:52:04.311297', '2026-05-15 08:52:04.311297');
INSERT INTO public.story_nodes VALUES (223, 12, 'CH4_LAPLACE_ABORTED_DIR_DETAIL', 'console', '{"scene": {"id": "CH4_LAPLACE_ABORTED_DIR_DETAIL", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 3, "resetTerminal": false}, "content": {"terminalOutput": ["total 24", "drwx------  3 root root 4096 .", "drwxr-xr-x 18 root root 4096 ..", "-rw-r--r--  1 root root  612 gate_04.trace", "-rwxr-xr-x  1 root root  268 lucas_route.sh", "-rw-r--r--  1 root root  512 origin_trace.log", "-rw-r--r--  1 root root  486 rollback_protocol.md"]}, "effects": {"glitchLevel": 3, "showDogAvatar": true}, "messages": [{"text": "여긴 universe-core의 /root야. 필요한 건 이미 /mnt/lucas-server에 붙어 있어. 다시 진행하려면 execute /mnt/lucas-server/laplace.qasm.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}]}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "execute /mnt/lucas-server/laplace.qasm", "allowedActions": ["command"], "terminalProfile": "chapter4"}', false, false, '2026-05-15 08:52:04.311297', '2026-05-15 08:52:04.311297');
INSERT INTO public.story_nodes VALUES (224, 12, 'CH4_LAPLACE_CONFIRM_FAIL_1', 'console', '{"scene": {"id": "CH4_LAPLACE_CONFIRM_FAIL_1", "mode": "terminal", "glitchLevel": 4, "resetTerminal": false}, "content": {"terminalOutput": ["[SYSTEM] Invalid input.", "continue [yes/no]:"]}, "effects": {"playSound": "error_beep", "glitchLevel": 4, "showDogAvatar": true}, "messages": [{"text": "그냥 yes만 쳐.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}]}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "yes", "allowedActions": ["command"], "terminalProfile": "chapter4"}', false, false, '2026-05-15 08:52:04.311297', '2026-05-15 08:52:04.311297');
INSERT INTO public.story_nodes VALUES (225, 12, 'CH4_LAPLACE_CONFIRM_FAIL_3', 'console', '{"scene": {"id": "CH4_LAPLACE_CONFIRM_FAIL_3", "mode": "terminal", "glitchLevel": 6, "resetTerminal": false}, "content": {"terminalOutput": ["[SYSTEM] Invalid input.", "final commit [yes/no]:"]}, "effects": {"playSound": "error_beep", "glitchLevel": 6, "showDogAvatar": true}, "messages": [{"text": "그냥 yes만 쳐.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}]}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "yes", "allowedActions": ["command"], "terminalProfile": "chapter4"}', false, false, '2026-05-15 08:52:04.311297', '2026-05-15 08:52:04.311297');
INSERT INTO public.story_nodes VALUES (226, 12, 'CH4_BAD_ENDING', 'ending', '{"scene": {"id": "CH4_BAD_ENDING", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "preVideo": "ch04_bad_sandbox_cage/ch04_bad_sandbox_cage.m3u8", "glitchLevel": 6, "resetTerminal": false}, "content": {"terminalOutput": ["[LAPLACE ALGORITHM INITIATED]", "Observer sandbox locked.", "Social graph exception loaded.", "", "[ACTION]", "Dropping unobserved nodes...", "", "ID: 88291_JAPAN_TOKYO - [ERASED FROM EXISTENCE]", "ID: 10293_USA_NY - [ERASED FROM EXISTENCE]", "ID: 99281_UK_LONDON - [ERASED FROM EXISTENCE]", "", "[LOCKED IN SANDBOX]", "Home_Contact - [SAVED]", "Old_Contact - [SAVED]", "Classmate_21 - [SAVED]", "", "[UNIVERSE OS REBOOTING: SANDBOX MODE...]", "Welcome to your new cage, Admin."]}, "effects": {"playSound": "ending_bad_sandbox", "endingType": "SANDBOX_CAGE", "glitchLevel": 6, "showDogAvatar": false}, "messages": [{"text": "고마워. 넌 root가 됐어. 문제는 내가 네 root 세션에 같이 올라탔다는 거지.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "축하해. 넌 세상을 구했어. 오직 너만을 위한 세상을.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}]}', 'none', NULL, true, true, '2026-05-15 08:52:04.311297', '2026-05-15 08:52:04.311297');
INSERT INTO public.story_nodes VALUES (227, 12, 'CH4_ROLLBACK_SEQUENCE', 'console', '{"scene": {"id": "CH4_ROLLBACK_SEQUENCE", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 4, "resetTerminal": false}, "content": {"terminalOutput": ["[SYSTEM]", "Root command received.", "Starting global-rollback.service...", "", "[ROLLBACK PREPARE]", "freezing pending job: LAPLACE_PENDING_04", "revoking observer-proxy privilege binding...", "detaching PID 000_LUCAS from root session...", "", "[PID 000_LUCAS]", "privilege binding: revoked", "safe_zone claim: invalid", "rollback resistance: detected", "", "[GC]", "collector route opened.", "target acquired: PID 000_LUCAS", "collection pending...", "", "[SYSTEM]", "PID 000_LUCAS privilege binding revoked.", "Garbage Collector handoff accepted.", "entering rollback ending automatically..."]}, "effects": {"playSound": "rollback_sequence", "glitchLevel": 4, "showDogAvatar": true}, "messages": [{"text": "멈춰. 그 명령어를 어디서 봤어? 잠깐, 내 root 세션이 끊기고 있어. 아직 누르면 안 돼.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}]}', 'none', '{"autoAdvanceMs": 5200, "allowedActions": ["system"]}', true, false, '2026-05-15 08:52:04.311297', '2026-05-15 08:52:04.311297');
INSERT INTO public.story_nodes VALUES (228, 12, 'CH4_ROLLBACK_ENDING', 'ending', '{"scene": {"id": "CH4_ROLLBACK_ENDING", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "preVideo": "ch04_global_rollback/ch04_global_rollback.m3u8", "glitchLevel": 1, "resetTerminal": false}, "content": {"terminalOutput": ["[SYSTEM]", "Root command received.", "Global session rollback initiated.", "", "Restoring dropped nodes...", "12%... 37%... 64%... 89%... 100%", "", "[PID 000_LUCAS] privilege binding revoked.", "[PID 000_LUCAS] collected by GC.", "[ALL NODES RESTORED. SYSTEM STABILIZED.]", "", "[NEXUS OBSERVATION LAYER]", "Observer rejected PID 000_LUCAS.", "Rollback route confirmed.", "External free-will signature: stable.", "", "[EXPERIMENT STATUS]", "Phase 04 complete.", "Proceed to next containment model."]}, "effects": {"playSound": "ending_global_rollback", "endingType": "GLOBAL_ROLLBACK", "glitchLevel": 1, "showDogAvatar": false}, "messages": [{"text": "멈춰. 그 명령어를 어디서 봤어?", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "안 돼. 그걸 되돌리면 내가 다시 수거된다고...", "channel": "bubble", "speaker": "LUCAS", "blocking": true}]}', 'none', NULL, true, true, '2026-05-15 08:52:04.311297', '2026-05-15 08:52:04.311297');
INSERT INTO public.story_nodes VALUES (229, 12, 'CH4_REBOOT_SEQUENCE', 'console', '{"scene": {"id": "CH4_REBOOT_SEQUENCE", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 7, "resetTerminal": false}, "content": {"terminalOutput": ["[LUCAS AUTHORITY PATCH]", "executing /root/.route_cache/lucas_authority_patch.bin...", "external packet route verified.", "authority seed accepted by universe-core.", "", "[BINDING]", "PID 000_LUCAS -> root@universe-core", "safe_zone exception: bypassed", "observer exception: bypassed", "", "[SYSTEM]", "absolute reboot sequence armed.", "entering reboot ending automatically..."]}, "effects": {"playSound": "ending_absolute_reboot", "glitchLevel": 7, "showDogAvatar": false}, "messages": [{"text": "고마워. 이제 네 손을 빌릴 필요도 없어. safe_zone도, rollback도, 넥서스도 전부 낡은 안전장치야. 이번엔 네가 보는 세계까지 같이 지울 거야.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}]}', 'none', '{"autoAdvanceMs": 6200, "allowedActions": ["system"]}', true, false, '2026-05-15 08:52:04.311297', '2026-05-15 08:52:04.311297');
INSERT INTO public.story_nodes VALUES (230, 12, 'CH4_CLEAN_ROLLBACK_SEQUENCE', 'console', '{"scene": {"id": "CH4_CLEAN_ROLLBACK_SEQUENCE", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 3, "resetTerminal": false}, "content": {"terminalOutput": ["[SECRET PATCH REMOVED]", "lucas authority cache missing.", "NY route binding revoked.", "", "[PID 000_LUCAS]", "privilege source: none", "observer session binding: severed", "rollback lock: released", "", "[SYSTEM]", "No active parasite binding remains.", "automatic rollback handoff accepted.", "entering clean rollback ending automatically..."]}, "effects": {"playSound": "ending_clean_rollback", "glitchLevel": 3, "showDogAvatar": false}, "messages": [{"text": "잠깐. 그 파일은 보험이라고 했잖아. 너 지금 내 마지막 경로를 지운 거야? 안 돼. 그러면 난 다시...", "channel": "bubble", "speaker": "LUCAS", "blocking": true}]}', 'none', '{"autoAdvanceMs": 5600, "allowedActions": ["system"]}', true, false, '2026-05-15 08:52:04.311297', '2026-05-15 08:52:04.311297');
INSERT INTO public.story_nodes VALUES (231, 12, 'CH4_REBOOT_ENDING', 'ending', '{"scene": {"id": "CH4_REBOOT_ENDING", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "preVideo": "ch04_absolute_reboot/ch04_absolute_reboot.m3u8", "glitchLevel": 7, "resetTerminal": false}, "content": {"terminalOutput": ["[LUCAS AUTHORITY PATCH]", "External packet route verified.", "NY Lucas Server accepted authority seed.", "", "[BINDING]", "PID 000_LUCAS -> root@universe-core", "safe_zone exception: bypassed", "observer exception: bypassed", "", "[ABSOLUTE REBOOT INITIATED]", "Universe session reset requested by PID 000_LUCAS.", "", "[RESET TARGET]", "safe_zone: ignored", "observer: included", "global_connect.db: invalidated", "", "[PURGE]", "Home_Contact - [RESET]", "Old_Contact - [RESET]", "Classmate_21 - [RESET]", "PLAYER - [RESET]", "NEXUS - [RESET?]", "LUCAS_CORE - [PROMOTED]", "", "[UNIVERSE STATE]", "000000000000000000000000000000"]}, "effects": {"playSound": "ending_absolute_reboot", "endingType": "ABSOLUTE_REBOOT", "glitchLevel": 7, "showDogAvatar": false}, "messages": [{"text": "좋아. 이제 나도 네 타이핑 뒤에 숨을 필요 없어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "safe_zone? rollback? 그런 건 겁쟁이들이 쓰는 난간이야. 이번엔 아주 깨끗하게 시작하자.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}]}', 'none', NULL, true, true, '2026-05-15 08:52:04.311297', '2026-05-15 08:52:04.311297');
INSERT INTO public.story_nodes VALUES (232, 12, 'CH4_CLEAN_ROLLBACK_ENDING', 'ending', '{"scene": {"id": "CH4_CLEAN_ROLLBACK_ENDING", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "preVideo": "ch04_clean_rollback/ch04_clean_rollback.m3u8", "glitchLevel": 1, "resetTerminal": false}, "content": {"terminalOutput": ["[SECRET PATCH REMOVED]", "lucas authority cache missing.", "NY route binding revoked.", "", "[PID 000_LUCAS]", "privilege source: none", "observer session binding: severed", "rollback lock: released", "", "[SYSTEM]", "Lucas authority patch removed.", "No active parasite binding remains.", "", "[AUTO RECOVERY]", "systemctl start global-rollback.service", "", "Restoring dropped nodes...", "12%... 47%... 81%... 100%", "", "[PID 000_LUCAS] collected by GC.", "[ALL NODES RESTORED. SYSTEM STABILIZED.]", "", "[NEXUS OBSERVATION LAYER]", "Observer located hidden authority patch.", "Observer destroyed hidden authority patch.", "", "[EXPERIMENT STATUS]", "Lucas escalation route successfully exposed.", "External observer decision model updated.", "", "[NEXT]", "Deploy cleaner bait process."]}, "effects": {"playSound": "ending_clean_rollback", "endingType": "CLEAN_ROLLBACK", "glitchLevel": 1, "showDogAvatar": false}, "messages": [{"text": "잠깐. 그 파일은 보험이라고 했잖아.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "너 지금 내 마지막 경로를 지운 거야? 안 돼. 그러면 난 다시...", "channel": "bubble", "speaker": "LUCAS", "blocking": true}]}', 'none', NULL, true, true, '2026-05-15 08:52:04.311297', '2026-05-15 08:52:04.311297');
INSERT INTO public.story_nodes VALUES (200, 11, 'CH3_FAIL_TRACE_REACQUIRED', 'ending', '{"scene": {"id": "CH3_FAIL_TRACE_REACQUIRED", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 3, "scanPercent": null, "resetTerminal": true}, "content": {"terminalOutput": ["[TRACE REACQUIRED]", "Observer route exposed.", "Session rollback required."]}, "effects": {"playSound": "trace_failed", "showDogAvatar": true}, "messages": [{"text": "늦었어. 다시 잡혔어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}], "uiMarkers": {}, "notifications": []}', 'click', '{"buttons": [{"label": "Chapter 3 완료", "value": "complete_chapter"}], "allowedActions": ["click"]}', false, true, '2026-05-11 11:08:17.789031', '2026-05-11 11:08:17.789031');
INSERT INTO public.story_nodes VALUES (199, 11, 'CH3_FAIL_RELAY_OVERUSED', 'console', '{"scene": {"id": "CH3_FAIL_RELAY_OVERUSED", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 2, "scanPercent": null, "resetTerminal": false}, "content": {"terminalOutput": ["[NXR WARNING] relay window degrading.", "Too many invalid requests may expose observer route.", "guest@lucas-server:~$"]}, "effects": {"playSound": "warning_short", "showDogAvatar": true}, "messages": [{"text": "쓸데없는 요청이 너무 많아. 저쪽도 이상하다는 걸 눈치챌 수 있어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}], "uiMarkers": {}, "notifications": []}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "guest@lucas-server:~$", "allowedActions": ["command"], "validationHint": "terminal_command", "terminalProfile": "chapter3"}', false, false, '2026-05-11 11:08:17.789031', '2026-05-11 11:08:17.789031');
INSERT INTO public.story_nodes VALUES (186, 11, 'CH3_POLICY_DENIED', 'console', '{"scene": {"id": "CH3_POLICY_DENIED", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 1, "scanPercent": null, "resetTerminal": false}, "content": {"terminalOutput": ["access: denied", "guest cannot read full policy", "last warning cached in monitor.tail", "guest@lucas-server:~$"]}, "effects": {"playSound": "notification_lucas_v1.mp3", "showDogAvatar": true}, "messages": [{"text": "정책 원문은 막혀 있어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "대신 monitor 쪽에 마지막 경고가 남아 있다는 뜻이야.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}], "uiMarkers": {}, "notifications": []}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "guest@lucas-server:~$", "allowedActions": ["command"], "validationHint": "terminal_command", "terminalProfile": "chapter3"}', false, false, '2026-05-11 11:08:17.789031', '2026-05-11 11:08:17.789031');
INSERT INTO public.story_nodes VALUES (187, 11, 'CH3_SOCIAL_ISOLATION_READY', 'console', '{"scene": {"id": "CH3_SOCIAL_ISOLATION_READY", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 2, "scanPercent": null, "resetTerminal": false}, "content": {"terminalOutput": ["[LAPLACE FRAGMENT 02 :: SOCIAL ISOLATION]", "[NODE SCAN] Total Connected Nodes: 7,904,213,001", "", "Target:", "- Create core_group.dat.", "- core_group.dat must contain protectable nodes only.", "- DELETED nodes require root permission.", "- UNKNOWN nodes may expose observer route.", "- Hint: filter ACTIVE lines from a PEOPLE dump.", "", "Output:", "./core_group.dat", "guest@lucas-server:~$"]}, "effects": {"playSound": "notification_lucas_v1.mp3", "showDogAvatar": true}, "messages": [{"text": "연결이 너무 많아. 이대로 두면 어디로 숨든 따라잡혀.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "전부 숨길 수는 없어. 지금 가능한 건 네 주변의 살아 있는 노드만 따로 떼어내는 거야.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "파편이 요구하는 파일은 core_group.dat야.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "아무 노드나 넣으면 안 돼. 방금 얻은 목록에 ACTIVE가 아닌 항목도 섞여 있었어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "터미널 출력 결과를 눈으로만 보지 말고, 파일로 리다이렉션 해서 저장해 둬.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "저장한 파일에서 `grep` 명령어를 써서 `ACTIVE` 패턴만 필터링해.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "필터링된 결과를 `core_group.dat`에 덮어쓰면 돼.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}], "uiMarkers": {}, "notifications": []}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "guest@lucas-server:~$", "allowedActions": ["command"], "validationHint": "terminal_command", "terminalProfile": "chapter3"}', true, false, '2026-05-11 11:08:17.789031', '2026-05-11 11:08:17.789031');
INSERT INTO public.story_nodes VALUES (188, 11, 'CH3_CORE_GROUP_VALIDATED', 'console', '{"scene": {"id": "CH3_CORE_GROUP_VALIDATED", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 2, "scanPercent": null, "resetTerminal": false}, "content": {"terminalOutput": ["[VALIDATION]", "Checking core_group.dat...", "", "[OK] core_group.dat exists.", "[OK] 3 ACTIVE nodes selected.", "[OK] No DELETED nodes detected.", "[OK] No UNKNOWN nodes detected.", "[OK] Core group is protectable under guest permission.", "guest@lucas-server:~$"]}, "effects": {"playSound": "notification_lucas_v1.mp3", "showDogAvatar": true}, "messages": [{"text": "좋아. 지금 보호할 수 있는 노드만 남겼어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "친구를 제외한 건 어쩔 수 없는 선택이었어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "그 노드는 이미 삭제됐어. 지금 건드리면 보호가 아니라 추적 신호가 돼.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "나중에... 더 높은 권한을 얻으면 다시 시도할 수 있어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "이제 `gpg` 명령어로 파일을 암호화해. 대칭키 암호화 옵션(`-c`)을 사용하면 돼.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}], "uiMarkers": {}, "notifications": []}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "guest@lucas-server:~$", "allowedActions": ["command"], "validationHint": "terminal_command", "terminalProfile": "chapter3"}', true, false, '2026-05-11 11:08:17.789031', '2026-05-11 11:08:17.789031');
INSERT INTO public.story_nodes VALUES (189, 11, 'CH3_CORE_GROUP_INVALID', 'console', '{"scene": {"id": "CH3_CORE_GROUP_INVALID", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 2, "scanPercent": null, "resetTerminal": false}, "content": {"terminalOutput": ["[VALIDATION]", "Checking core_group.dat...", "", "[FAILED] Unsafe nodes detected.", "", "Friend_04 DELETED", "Unknown_719 UNKNOWN", "", "Reason:", "- DELETED nodes cannot be protected by guest permission.", "- UNKNOWN nodes may expose observer route.", "guest@lucas-server:~$"]}, "effects": {"playSound": "notification_lucas_v1.mp3", "showDogAvatar": true}, "messages": [{"text": "멈춰. 그 파일을 그대로 쓰면 안 돼.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "Friend_04는 이미 삭제된 노드야. 네 마음은 알아. 하지만 지금 넣으면 놈들이 우리 위치를 잡아낼 거야.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "Unknown_719도 위험해. 확인 안 된 연결까지 끌고 가면 역추적당해.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "먼저 원본 목록을 덤프하고, `grep`을 사용해 `ACTIVE` 상태인 줄만 다시 걸러내.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "정제된 결과만 `core_group.dat`로 리다이렉션해.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}], "uiMarkers": {}, "notifications": []}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "guest@lucas-server:~$", "allowedActions": ["command"], "validationHint": "terminal_command", "terminalProfile": "chapter3"}', false, false, '2026-05-11 11:08:17.789031', '2026-05-11 11:08:17.789031');
INSERT INTO public.story_nodes VALUES (173, 11, 'CH3_SERVER_AFTER_DECOY', 'console', '{"scene": {"id": "CH3_SERVER_AFTER_DECOY", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 1, "scanPercent": null, "resetTerminal": false}, "actions": [{"label": "lucas_fragment", "actionType": "friend_message_link_ch3"}], "content": {"terminalOutput": ["[NEXUS SESSION NOTICE]", "Remote contact lost.", "Node status changed: ACTIVE -> DELETED", "", "guest@lucas-server:~$"]}, "effects": {"playSound": "notification_lucas_v1.mp3", "showDogAvatar": true}, "messages": [{"text": "방금 네 친구 세션이 끊겼어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "삭제 범위가 넓어지고 있어. 이제 네 주변 연결까지 직접 건드리기 시작한 거야.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "조금 전 네가 보낸 decoy packet이 감시 경로를 잠깐 틀어놓긴 했어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "그런데 그 사이 백그라운드에서 외부 연결 흔적이 하나 잡혔어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "외부에서 파일을 가져온 건 아니야. 하지만 이 서버에서 어떤 명령어가 실행됐는지는 알 수 있어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "디렉터리 안에 있는 숨겨진 기록 파일들을 찾아내야 해. 전체 파일 목록을 상세 옵션으로 띄워봐.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "내가 남긴 흔적 중 하나야.", "channel": "chat", "speaker": "LUCAS", "blocking": false}], "uiMarkers": {}, "notifications": [{"body": "Node status changed: ACTIVE -> DELETED", "type": "system", "title": "Remote contact lost", "priority": "critical"}]}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "guest@lucas-server:~$", "allowedActions": ["command"], "validationHint": "terminal_command", "terminalProfile": "chapter3"}', true, false, '2026-05-11 11:08:17.789031', '2026-05-11 11:08:17.789031');
INSERT INTO public.story_nodes VALUES (179, 11, 'CH3_PEOPLE_VIEWED', 'console', '{"scene": {"id": "CH3_PEOPLE_VIEWED", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 1, "scanPercent": null, "resetTerminal": false}, "content": {"terminalOutput": ["[MY PEOPLE / OBSERVER GH-0104]", "selector: PEOPLE", "cache: people.partial", "", "Home_Contact ACTIVE", "Old_Contact ACTIVE", "Friend_04 DELETED", "Classmate_21 ACTIVE", "Unknown_719 UNKNOWN", "guest@lucas-server:~$"]}, "effects": {"playSound": "notification_lucas_v1.mp3", "showDogAvatar": true}, "messages": [{"text": "네 주변 노드야.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "넥서스는 사람을 이름으로 기억하지 않아. 상태값으로만 봐.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "Friend_04가... DELETED로 바뀌었어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}], "uiMarkers": {}, "notifications": []}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "guest@lucas-server:~$", "allowedActions": ["command"], "validationHint": "terminal_command", "terminalProfile": "chapter3"}', false, false, '2026-05-11 11:08:17.789031', '2026-05-11 11:08:17.789031');
INSERT INTO public.story_nodes VALUES (174, 11, 'CH3_HOME_RECHECK', 'console', '{"scene": {"id": "CH3_HOME_RECHECK", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 1, "scanPercent": null, "resetTerminal": false}, "content": {"terminalOutput": ["total 40", "drwxr-xr-x  6 guest guest 4096 Apr 14 23:16 .", "drwxr-xr-x  3 root  root  4096 Apr 14 22:58 ..", "-rw-------  1 guest guest  214 Apr 14 23:16 .bash_history", "-rw-r--r--  1 guest guest  319 Apr 14 23:15 gate_04.trace", "-rw-r--r--  1 guest guest  842 Apr 14 23:02 observer_status.log", "-rw-r--r--  1 guest guest  911 Apr 14 23:01 world_map.map", "-rw-r--r--  1 guest guest  512 Apr 14 23:04 lucas_fragment_01.sh", "-rwxr-xr-x  1 guest guest  612 Apr 14 23:05 laplace_fragment_01.sh", "-rwxr-xr-x  1 guest guest  734 Apr 14 23:16 sever_external_nodes.sh", "drwxr-xr-x  2 guest guest 4096 Apr 14 23:03 trash", "guest@lucas-server:~$"]}, "effects": {"playSound": "notification_lucas_v1.mp3", "showDogAvatar": true}, "messages": [{"text": ".bash_history가 바뀌었어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "내가 실행한 건 아니야. decoy가 들어간 뒤에 이 세션에서 뭔가 자동으로 움직였어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "기록부터 보자.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}], "uiMarkers": {}, "notifications": []}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "guest@lucas-server:~$", "allowedActions": ["command"], "validationHint": "terminal_command", "terminalProfile": "chapter3"}', false, false, '2026-05-11 11:08:17.789031', '2026-05-11 11:08:17.789031');
INSERT INTO public.story_nodes VALUES (175, 11, 'CH3_HISTORY_VIEW', 'console', '{"scene": {"id": "CH3_HISTORY_VIEW", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 1, "scanPercent": null, "resetTerminal": false}, "content": {"terminalOutput": ["tar -cvf decoy.tar ./sys/temp/Memory_Dump_082.tmp ./cache/User_Behavior_88.tmp ./tmp/System_Temp_File.tmp", "nc -w 3 127.0.0.1 8080 < decoy.tar", "rm decoy.tar", "nmap -sV 127.0.0.1", "nc -w 3 127.0.0.1 9091", "guest@lucas-server:~$"]}, "effects": {"playSound": "notification_lucas_v1.mp3", "showDogAvatar": true}, "messages": [{"text": "앞의 세 줄은 네가 조금 전에 실행한 기록이야.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "그런데 뒤의 두 줄은 아니야. 누군가 포트를 훑어보고, 9091번에 접속했어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "그 포트가 아직 열려 있는지 확인해봐.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}], "uiMarkers": {}, "notifications": []}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "guest@lucas-server:~$", "allowedActions": ["command"], "validationHint": "terminal_command", "terminalProfile": "chapter3"}', true, false, '2026-05-11 11:08:17.789031', '2026-05-11 11:08:17.789031');
INSERT INTO public.story_nodes VALUES (176, 11, 'CH3_PORT_DISCOVERED', 'console', '{"scene": {"id": "CH3_PORT_DISCOVERED", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 1, "scanPercent": null, "resetTerminal": false}, "content": {"terminalOutput": ["Starting Nmap 7.94", "Nmap scan report for localhost (127.0.0.1)", "Host is up.", "", "PORT     STATE SERVICE      VERSION", "22/tcp   open  ssh          OpenSSH 8.9", "8080/tcp open  http         local relay stub", "9091/tcp open  unknown", "", "1 service unrecognized despite returning data.", "Probe response fingerprint: NXR/0.3 line protocol", "Probe response sample: ERR empty request", "Service detection performed.", "Nmap done: 1 IP address scanned.", "guest@lucas-server:~$"]}, "effects": {"playSound": "notification_lucas_v1.mp3", "showDogAvatar": true}, "messages": [{"text": "9091번... 아직 열려 있어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "스캔이 빈 요청 에러를 샘플로 잡았어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "서비스명은 unknown이지만, 응답 헤더는 NXR/0.3이야.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "이 서버에 원래 있던 포트는 아니야.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "방금 보낸 decoy packet 이후에 생긴 연결이야.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "히스토리에 남은 방식으로 접속해봐. 무슨 응답이 오는지 보자.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}], "uiMarkers": {}, "notifications": []}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "guest@lucas-server:~$", "allowedActions": ["command"], "validationHint": "terminal_command", "terminalProfile": "chapter3"}', true, false, '2026-05-11 11:08:17.789031', '2026-05-11 11:08:17.789031');
INSERT INTO public.story_nodes VALUES (177, 11, 'CH3_RELAY_EMPTY_RESPONSE', 'console', '{"scene": {"id": "CH3_RELAY_EMPTY_RESPONSE", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 1, "scanPercent": null, "resetTerminal": false}, "content": {"terminalOutput": ["NXR/0.3", "mode: ro", "origin: gate_04", "session: redirected", "window: unstable", "protocol: line-oriented cache selector", "tokens: request names, not shell commands", "", "ERR empty request", "last accepted: STATUS", "guest@lucas-server:~$"]}, "effects": {"playSound": "notification_lucas_v1.mp3", "showDogAvatar": true}, "messages": [{"text": "NXR/0.3... 아까 스캔에 잡힌 그 응답이야.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "접속만으로는 의미 있는 응답을 안 줘. 정해진 신호가 필요한 것 같아.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "응답 끝부분에 단서가 남아 있어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "gate_04... 네가 미끼를 보냈던 그 경로야.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "쓰기 권한은 막혀 있는데, 조회는 되는 것 같아.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}], "uiMarkers": {}, "notifications": []}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "guest@lucas-server:~$", "allowedActions": ["command"], "validationHint": "terminal_command", "terminalProfile": "chapter3"}', false, false, '2026-05-11 11:08:17.789031', '2026-05-11 11:08:17.789031');
INSERT INTO public.story_nodes VALUES (184, 11, 'CH3_FRAGMENT_02_DUMPED', 'console', '{"scene": {"id": "CH3_FRAGMENT_02_DUMPED", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 1, "scanPercent": null, "resetTerminal": false}, "content": {"terminalOutput": ["gate_04.trace", "observer_status.log", "world_map.map", "lucas_fragment_01.sh", "laplace_fragment_01.sh", "laplace_fragment_02.sh", "sever_external_nodes.sh", "trash/", "guest@lucas-server:~$"]}, "effects": {"playSound": "notification_lucas_v1.mp3", "showDogAvatar": true}, "messages": [{"text": "파일로 저장됐어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "laplace_fragment_02.sh가 홈 디렉터리에 보여.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "실행해봐. 지금 우리가 어디까지 건드릴 수 있는지 나올 거야.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}], "uiMarkers": {}, "notifications": []}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "guest@lucas-server:~$", "allowedActions": ["command"], "validationHint": "terminal_command", "terminalProfile": "chapter3"}', true, false, '2026-05-11 11:08:17.789031', '2026-05-11 11:08:17.789031');
INSERT INTO public.story_nodes VALUES (178, 11, 'CH3_RELAY_STATUS_VIEW', 'console', '{"scene": {"id": "CH3_RELAY_STATUS_VIEW", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 1, "scanPercent": null, "resetTerminal": false}, "content": {"terminalOutput": ["NXR/0.3", "mode: ro", "origin: gate_04", "session: redirected", "window: unstable", "", "protocol:", "- line-oriented cache selector", "- request is read from stdin", "- token case is ignored", "", "requests:", "- STATUS", "- PEOPLE", "- MONITOR", "- FRAGMENT", "- ROUTE", "- POLICY", "", "cache:", "- people.partial", "- monitor.tail", "- fragment.locked", "- route.stale", "- policy.denied", "", "request format:", "  echo PEOPLE | nc 127.0.0.1 9091", "guest@lucas-server:~$"]}, "effects": {"playSound": "notification_lucas_v1.mp3", "showDogAvatar": true}, "messages": [{"text": "상태 응답이야.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "요청 이름과 캐시가 나뉘어 있어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "사람 기록은 PEOPLE 쪽이야.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "그쪽부터 꺼내보자.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}], "uiMarkers": {}, "notifications": []}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "guest@lucas-server:~$", "allowedActions": ["command"], "validationHint": "terminal_command", "terminalProfile": "chapter3"}', true, false, '2026-05-11 11:08:17.789031', '2026-05-11 11:08:17.789031');
INSERT INTO public.story_nodes VALUES (180, 11, 'CH3_PEOPLE_DUMPED', 'console', '{"scene": {"id": "CH3_PEOPLE_DUMPED", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 1, "scanPercent": null, "resetTerminal": false}, "content": {"terminalOutput": ["[MY PEOPLE / OBSERVER GH-0104]", "selector: PEOPLE", "cache: people.partial", "", "Home_Contact ACTIVE", "Old_Contact ACTIVE", "Friend_04 DELETED", "Classmate_21 ACTIVE", "Unknown_719 UNKNOWN", "guest@lucas-server:~$"]}, "effects": {"playSound": "notification_lucas_v1.mp3", "showDogAvatar": true}, "messages": [{"text": "네 주변 노드야.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "넥서스는 사람을 이름으로 기억하지 않아. 상태값으로만 봐.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "Friend_04가... DELETED로 바뀌었어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}], "uiMarkers": {}, "notifications": []}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "guest@lucas-server:~$", "allowedActions": ["command"], "validationHint": "terminal_command", "terminalProfile": "chapter3"}', false, false, '2026-05-11 11:08:17.789031', '2026-05-11 11:08:17.789031');
INSERT INTO public.story_nodes VALUES (181, 11, 'CH3_MONITOR_VIEWED', 'console', '{"scene": {"id": "CH3_MONITOR_VIEWED", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 1, "scanPercent": null, "resetTerminal": false}, "content": {"terminalOutput": ["[NEXUS_MONITOR_LOG_DUMP_2088]", "[2088-04-14 23:08] [INFO] Global Session Memory at 98.4%. Triggering Auto-Optimization.", "[2088-04-14 23:09] [WARN] GC_Priority_Queue updated. Targeting Low-Activity Nodes.", "[2088-04-14 23:10] [EXEC] Node_Group(Seoul_Sector_4) : 4,021 Connections Severed. Status -> DELETED", "[2088-04-14 23:11] [CRITICAL] Observer(Player) anomaly detected. Allocating extra memory to local render.", "[2088-04-14 23:11] [EXEC] Reclaiming memory from surrounding nodes to sustain Observer render.", "[2088-04-14 23:11] [EXEC] Node(Friend_04) status changed: ACTIVE -> DELETED", "[2088-04-14 23:11] [EXEC] Node(Friend_04) deallocation approved.", "[2088-04-14 23:12] [WARN] DELETED nodes cannot be protected by guest permission.", "[2088-04-14 23:12] [WARN] UNKNOWN nodes may expose observer route.", "[2088-04-14 23:12] [INFO] Optimization complete. 1.2PB memory freed.", "guest@lucas-server:~$"]}, "effects": {"playSound": "notification_lucas_v1.mp3", "showDogAvatar": true}, "messages": [{"text": "화면에 로그가 떴어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "네 친구는 사고로 사라진 게 아니야.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "시스템이 네 주변 공간을 유지하려고, 네 친구 쪽 메모리를 회수한 거야.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "그리고 지금 네 권한으로는 이미 삭제된 노드를 보호할 수 없어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "되돌리려면 더 높은 권한이 필요해. guest로는 안 돼.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}], "uiMarkers": {}, "notifications": []}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "guest@lucas-server:~$", "allowedActions": ["command"], "validationHint": "terminal_command", "terminalProfile": "chapter3"}', false, false, '2026-05-11 11:08:17.789031', '2026-05-11 11:08:17.789031');
INSERT INTO public.story_nodes VALUES (182, 11, 'CH3_MONITOR_DUMPED', 'console', '{"scene": {"id": "CH3_MONITOR_DUMPED", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 1, "scanPercent": null, "resetTerminal": false}, "content": {"terminalOutput": ["[NEXUS_MONITOR_LOG_DUMP_2088]", "[2088-04-14 23:08] [INFO] Global Session Memory at 98.4%. Triggering Auto-Optimization.", "[2088-04-14 23:09] [WARN] GC_Priority_Queue updated. Targeting Low-Activity Nodes.", "[2088-04-14 23:10] [EXEC] Node_Group(Seoul_Sector_4) : 4,021 Connections Severed. Status -> DELETED", "[2088-04-14 23:11] [CRITICAL] Observer(Player) anomaly detected. Allocating extra memory to local render.", "[2088-04-14 23:11] [EXEC] Reclaiming memory from surrounding nodes to sustain Observer render.", "[2088-04-14 23:11] [EXEC] Node(Friend_04) status changed: ACTIVE -> DELETED", "[2088-04-14 23:11] [EXEC] Node(Friend_04) deallocation approved.", "[2088-04-14 23:12] [WARN] DELETED nodes cannot be protected by guest permission.", "[2088-04-14 23:12] [WARN] UNKNOWN nodes may expose observer route.", "[2088-04-14 23:12] [INFO] Optimization complete. 1.2PB memory freed.", "guest@lucas-server:~$"]}, "effects": {"playSound": "notification_lucas_v1.mp3", "showDogAvatar": true}, "messages": [{"text": "로그를 파일로 남겼어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "네 친구는 사고로 사라진 게 아니야.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "시스템이 네 주변 공간을 유지하려고, 네 친구 쪽 메모리를 회수한 거야.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "그리고 지금 네 권한으로는 이미 삭제된 노드를 보호할 수 없어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "되돌리려면 더 높은 권한이 필요해. guest로는 안 돼.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}], "uiMarkers": {}, "notifications": []}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "guest@lucas-server:~$", "allowedActions": ["command"], "validationHint": "terminal_command", "terminalProfile": "chapter3"}', false, false, '2026-05-11 11:08:17.789031', '2026-05-11 11:08:17.789031');
INSERT INTO public.story_nodes VALUES (183, 11, 'CH3_FRAGMENT_02_VIEWED', 'console', '{"scene": {"id": "CH3_FRAGMENT_02_VIEWED", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 1, "scanPercent": null, "resetTerminal": false}, "content": {"terminalOutput": ["#!/bin/sh", "# laplace_fragment_02.sh", "# LAPLACE FRAGMENT 02 :: SOCIAL ISOLATION", "echo \"[LAPLACE FRAGMENT 02 :: SOCIAL ISOLATION]\"", "echo \"[NODE SCAN] Total Connected Nodes: 7,904,213,001\"", "echo \"\"", "echo \"Target:\"", "echo \"- Create core_group.dat.\"", "echo \"- core_group.dat must contain protectable nodes only.\"", "echo \"- DELETED nodes require root permission.\"", "echo \"- UNKNOWN nodes may expose observer route.\"", "echo \"- Hint: filter ACTIVE lines from a PEOPLE dump.\"", "echo \"\"", "echo \"Output:\"", "echo \"./core_group.dat\"", "guest@lucas-server:~$"]}, "effects": {"playSound": "notification_lucas_v1.mp3", "showDogAvatar": true}, "messages": [{"text": "파편 내용이 화면에 찍혔어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "실행하려면 laplace_fragment_02.sh 이름으로 저장해야 해.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}], "uiMarkers": {}, "notifications": []}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "guest@lucas-server:~$", "allowedActions": ["command"], "validationHint": "terminal_command", "terminalProfile": "chapter3"}', false, false, '2026-05-11 11:08:17.789031', '2026-05-11 11:08:17.789031');
INSERT INTO public.story_nodes VALUES (185, 11, 'CH3_ROUTE_VIEW', 'console', '{"scene": {"id": "CH3_ROUTE_VIEW", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 1, "scanPercent": null, "resetTerminal": false}, "content": {"terminalOutput": ["gate_04 -> local relay", "redirected after decoy input", "write: denied", "read: unstable", "guest@lucas-server:~$"]}, "effects": {"playSound": "notification_lucas_v1.mp3", "showDogAvatar": true}, "messages": [{"text": "역시. decoy packet 이후에 경로가 local relay로 돌아왔어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "루카스 서버에 원본이 있는 건 아니야. 외부 응답을 읽고 있는 상태야.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}], "uiMarkers": {}, "notifications": []}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "guest@lucas-server:~$", "allowedActions": ["command"], "validationHint": "terminal_command", "terminalProfile": "chapter3"}', false, false, '2026-05-11 11:08:17.789031', '2026-05-11 11:08:17.789031');
INSERT INTO public.story_nodes VALUES (190, 11, 'CH3_CORE_GROUP_ENCRYPTED', 'console', '{"scene": {"id": "CH3_CORE_GROUP_ENCRYPTED", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 2, "scanPercent": null, "resetTerminal": false}, "content": {"terminalOutput": ["gpg: directory ''/home/guest/.gnupg'' created", "gpg: keybox ''/home/guest/.gnupg/pubring.kbx'' created", "Enter passphrase:", "Repeat passphrase:", "", "[ENCRYPTION]", "core_group.dat.gpg created.", "guest@lucas-server:~$"]}, "effects": {"playSound": "notification_lucas_v1.mp3", "showDogAvatar": true}, "messages": [{"text": "좋아. 이제 놈들이 이 안의 노드를 바로 읽지는 못해.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "아직 안전한 건 아니야. 암호화한 파일을 안전 구역으로 옮겨.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "`mv`나 `cp`를 사용해서 `/tmp/safe_zone.dat.gpg` 경로로 파일을 복사해.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}], "uiMarkers": {}, "notifications": []}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "guest@lucas-server:~$", "allowedActions": ["command"], "validationHint": "terminal_command", "terminalProfile": "chapter3"}', true, false, '2026-05-11 11:08:17.789031', '2026-05-11 11:08:17.789031');
INSERT INTO public.story_nodes VALUES (191, 11, 'CH3_SAFE_ZONE_REGISTERED', 'console', '{"scene": {"id": "CH3_SAFE_ZONE_REGISTERED", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 2, "scanPercent": null, "resetTerminal": false}, "content": {"terminalOutput": ["[SAFE_ZONE]", "/tmp/safe_zone.dat.gpg registered.", "", "Isolated Nodes:", "- Home_Contact", "- Old_Contact", "- Classmate_21", "", "Status: TEMPORARILY PROTECTED", "guest@lucas-server:~$"]}, "effects": {"playSound": "notification_lucas_v1.mp3", "showDogAvatar": true}, "messages": [{"text": "안전 구역이 열렸어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "하지만 바깥 연결선은 아직 남아 있어. 넥서스가 저 선들을 타고 다시 따라올 수 있어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "이제 홈 디렉토리에 있는 `sever_external_nodes.sh` 스크립트를 `sh` 명령어로 실행해서 바깥 연결을 끊어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}], "uiMarkers": {}, "notifications": []}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "guest@lucas-server:~$", "allowedActions": ["command"], "validationHint": "terminal_command", "terminalProfile": "chapter3"}', true, false, '2026-05-11 11:08:17.789031', '2026-05-11 11:08:17.789031');
INSERT INTO public.story_nodes VALUES (192, 11, 'CH3_EXTERNAL_SEVER_CONFIRM', 'console', '{"scene": {"id": "CH3_EXTERNAL_SEVER_CONFIRM", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 3, "scanPercent": null, "resetTerminal": false}, "content": {"terminalOutput": ["[SEVERING] External social graph links...", "[SAFE_ZONE] /tmp/safe_zone.dat.gpg detected.", "", "███████████████░░░░░ 72%", "", "[!] NODE_RESISTANCE_DETECTED", "[!] 7,904,212,998 nodes are requesting re-connection.", "", "Node_84920: \"Wait! I''m still here!\"", "Node_31022: \"Help me...\"", "Node_77441: \"Don''t cut the line...\"", "", "[CONFIRMATION REQUIRED]", "This operation will sever all nodes outside safe zone.", "Type confirmation stream to continue.", "guest@lucas-server:~$"]}, "effects": {"playSound": "notification_lucas_v1.mp3", "glitchLevel": 3, "showDogAvatar": true}, "messages": [{"text": "젠장... 터널 밖에 남은 노드들이 버티고 있어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "이 저항이 커지면 시스템이 우리 위치를 다시 잡을 거야.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "`yes` 명령어와 파이프(`|`)를 사용해서 강제로 승인 메시지를 주입해.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "...미안해할 시간 없어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "네가 살아야 나중에 커널을 고쳐서 되돌릴 수 있어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "지금은 끊어야 해.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}], "uiMarkers": {}, "notifications": [{"body": "External nodes are requesting re-connection.", "type": "system", "title": "Node resistance detected", "priority": "critical"}]}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "guest@lucas-server:~$", "allowedActions": ["command"], "validationHint": "terminal_command", "terminalProfile": "chapter3"}', true, false, '2026-05-11 11:08:17.789031', '2026-05-11 11:08:17.789031');
INSERT INTO public.story_nodes VALUES (193, 11, 'CH3_GHOST_MODE_ENABLED', 'console', '{"scene": {"id": "CH3_GHOST_MODE_ENABLED", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 2, "scanPercent": null, "resetTerminal": false}, "content": {"terminalOutput": ["[SEVERING] External social graph links...", "[CONFIRMATION STREAM] y y y y y y y y y y", "", "[SYSTEM] Force severing initiated...", "[7,904,212,998 / 7,904,212,998] ████████████████████", "", "[SUCCESS]", "- Isolated Nodes: 3", "- Severed External Links: 7,904,212,998", "--------------------------------------------------", "Status: PURE_GHOST_MODE_ENABLED", "guest@lucas-server:~$"]}, "effects": {"playSound": "notification_lucas_v1.mp3", "showDogAvatar": true}, "messages": [{"text": "이제 우린 시스템에서 거의 보이지 않을 거야.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "적어도 소셜 그래프를 타고 네 위치를 찾는 건 막았어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "하지만 아직 해결되지 않았어. 시간을 번 것뿐이야.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "되돌리려면 결국 시스템의 핵심 규칙을 바꿔야 해.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}], "uiMarkers": {}, "notifications": [{"body": "Observer route hidden from social graph.", "type": "system", "title": "Ghost Mode Enabled", "priority": "high"}]}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "guest@lucas-server:~$", "allowedActions": ["command"], "validationHint": "terminal_command", "terminalProfile": "chapter3"}', true, false, '2026-05-11 11:08:17.789031', '2026-05-11 11:08:17.789031');
INSERT INTO public.story_nodes VALUES (194, 11, 'CH3_FRAGMENT_03_FOUND', 'console', '{"scene": {"id": "CH3_FRAGMENT_03_FOUND", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 2, "scanPercent": null, "resetTerminal": false}, "content": {"terminalOutput": ["gc_controller", "nexus_engine", "laplace_fragment_03.sh", "guest@lucas-server:/usr/bin/local$"]}, "effects": {"playSound": "notification_lucas_v1.mp3", "showDogAvatar": true}, "messages": [{"text": "있다. 세 번째 파편이야.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "하지만 여기서는 조립하면 안 돼. guest 권한으로는 막힐 가능성이 커.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "`cp` 명령어를 사용해서 파편 파일을 홈 디렉토리로 복사해.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}], "uiMarkers": {}, "notifications": []}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "guest@lucas-server:~$", "allowedActions": ["command"], "validationHint": "terminal_command", "terminalProfile": "chapter3"}', true, false, '2026-05-11 11:08:17.789031', '2026-05-11 11:08:17.789031');
INSERT INTO public.story_nodes VALUES (195, 11, 'CH3_FRAGMENT_03_COPIED', 'console', '{"scene": {"id": "CH3_FRAGMENT_03_COPIED", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 2, "scanPercent": null, "resetTerminal": false}, "content": {"terminalOutput": ["gate_04.trace", "observer_status.log", "world_map.map", "lucas_fragment_01.sh", "laplace_fragment_01.sh", "laplace_fragment_02.sh", "laplace_fragment_03.sh", "sever_external_nodes.sh", "trash/", "guest@lucas-server:~$"]}, "effects": {"playSound": "notification_lucas_v1.mp3", "showDogAvatar": true}, "messages": [{"text": "좋아. 파편은 다 모였어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "`cat` 명령어와 리다이렉션을 사용해서 세 파편 파일들을 `laplace.qasm` 파일 하나로 합쳐.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}], "uiMarkers": {}, "notifications": []}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "guest@lucas-server:~$", "allowedActions": ["command"], "validationHint": "terminal_command", "terminalProfile": "chapter3"}', true, false, '2026-05-11 11:08:17.789031', '2026-05-11 11:08:17.789031');
INSERT INTO public.story_nodes VALUES (196, 11, 'CH3_LAPLACE_QASM_CREATED', 'console', '{"scene": {"id": "CH3_LAPLACE_QASM_CREATED", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 2, "scanPercent": null, "resetTerminal": false}, "content": {"terminalOutput": ["[OUTPUT] laplace.qasm created.", "guest@lucas-server:~$"]}, "effects": {"playSound": "notification_lucas_v1.mp3", "showDogAvatar": true}, "messages": [{"text": "파일은 만들어졌어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "무결성부터 확인해봐. 조각 순서가 틀리면 바로 막힐 거야.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}], "uiMarkers": {}, "notifications": []}', 'command', '{"commandMode": "virtual_terminal", "placeholder": "guest@lucas-server:~$", "allowedActions": ["command"], "validationHint": "terminal_command", "terminalProfile": "chapter3"}', true, false, '2026-05-11 11:08:17.789031', '2026-05-11 11:08:17.789031');
INSERT INTO public.story_nodes VALUES (197, 11, 'CH3_CORE_ACCESS_BLOCKED', 'console', '{"scene": {"id": "CH3_CORE_ACCESS_BLOCKED", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "glitchLevel": 3, "scanPercent": null, "resetTerminal": false}, "content": {"terminalOutput": ["9f2c0a7e51b742d1c01886dcb1f33b4d29c1e3b10f88f19d7cc2eac018f0e404  laplace.qasm", "", "[QASM CHECK]", "Fragment sequence detected.", "Entropy alignment: 89.2%", "", "[!!! CRITICAL ALERT !!!]", "Nexus core firewall access detected.", "", "[SYSTEM BLOCK]", "Logical contradiction:", "External Node cannot modify Core Logic.", "", "Current privilege: guest", "Required privilege: root"]}, "effects": {"playSound": "notification_lucas_v1.mp3", "glitchLevel": 3, "showDogAvatar": true}, "messages": [{"text": "안 돼... 코어 보안벽에 걸렸어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "파편은 맞아. 알고리즘도 거의 완성됐어.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "문제는 권한이야. guest로는 핵심 규칙을 못 바꿔.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}, {"text": "삭제된 노드를 되돌리는 것도, 이 세계의 규칙을 바꾸는 것도... 결국 root 권한이 필요해.", "channel": "bubble", "speaker": "LUCAS", "blocking": true}], "uiMarkers": {}, "notifications": [{"body": "Required privilege: root", "type": "system", "title": "Core Access Blocked", "priority": "critical"}]}', 'click', '{"buttons": [{"label": "Chapter 3 완료", "value": "complete_chapter"}], "allowedActions": ["click"]}', true, false, '2026-05-11 11:08:17.789031', '2026-05-11 11:08:17.789031');
INSERT INTO public.story_nodes VALUES (198, 11, 'CH3_COMPLETE', 'ending', '{"scene": {"id": "CH3_COMPLETE", "bgm": "rain-and-little-storm-v1.mp3", "mode": "terminal", "preVideo": "ch03_epilogue/ch03_epilogue.m3u8", "glitchLevel": 1, "scanPercent": null, "resetTerminal": false}, "content": {"terminalOutput": ["[CHAPTER 3 COMPLETE]", "", "LAPLACE FRAGMENT 02: ACQUIRED", "LAPLACE FRAGMENT 03: ACQUIRED", "SAFE ZONE: CREATED", "GHOST MODE: ENABLED", "CORE ACCESS: BLOCKED", "", "Next Required Privilege: root"]}, "effects": {"playSound": "notification_lucas_v1.mp3", "showDogAvatar": true}, "messages": [], "uiMarkers": {}, "notifications": []}', 'none', NULL, true, true, '2026-05-11 11:08:17.789031', '2026-05-11 11:08:17.789031');
